#include "SignalThread.h"

using namespace SIM::Coin3D::Quarter;

SignalThread::SignalThread(void)
  : isstopped(false)
{
}

SignalThread::~SignalThread()
{
}

void
SignalThread::trigger(void)
{
  // lock first to make sure the QThread is actually waiting for a signal
  this->mutex.lock();
  this->waitcond.wakeOne();
  this->mutex.unlock();
}

void
SignalThread::stopThread(void)
{
  this->mutex.lock();
  this->isstopped = true;
  this->waitcond.wakeOne();
  this->mutex.unlock();
}


void
SignalThread::run(void)
{
  this->mutex.lock();
  while (!this->isstopped) {
    // just wait, and trigger every time we receive a signal
    this->waitcond.wait(&this->mutex);
    if (!this->isstopped) {
      emit triggerSignal();
    }
  }
  this->mutex.unlock();
}","lineStart":1,"lineEnd":77,"totalLines":77,"truncated":false}},"title":"repos/ruangong-0707/quarter/src/Quarter/SignalThread.cpp","time":{"start":1783416294434,"end":1783416294443}},"id":"prt_f3be509f8001KYyWgFtxAnOdb6","sessionID":"ses_0c41eb87affe2UivlPykZoWGQ5","messageID":"msg_f3be4f631001JYFJcQeX6D1xxn"}}

